import SwiftUI
import UniformTypeIdentifiers

enum StudioPanel:String,CaseIterable,Identifiable{case library="Library",templates="Templates",vibe="Vibe AI",code="Code",build="Build",widget="Widget";var id:String{rawValue};var icon:String{switch self{case .library:return "square.grid.2x2";case .templates:return "square.stack.3d.up";case .vibe:return "sparkles";case .code:return "chevron.left.forwardslash.chevron.right";case .build:return "hammer";case .widget:return "square.grid.2x2.fill"}}}

struct Studio2View:View{
    @EnvironmentObject private var store:StudioStore;@EnvironmentObject private var github:GitHubBuildManager
    @State private var leftPanel:StudioPanel=.library;@State private var bottomPanel:StudioPanel?=.code;@State private var showInspector=false;@State private var showLeftPanel=false;@State private var showGitHub=false;@State private var showNewProject=false;@State private var newName="";@State private var newTemplate:StudioTemplate=.blank
    var body:some View{GeometryReader{proxy in if proxy.size.width>=900{desktop}else{compact}}.tint(.indigo).background(Color(uiColor:.systemGroupedBackground)).sheet(isPresented:$showGitHub){ReyForgeGitHubSettings().environmentObject(github)}.sheet(isPresented:$showNewProject){NavigationStack{Form{Section("Project"){TextField("App name",text:$newName);Picker("Template",selection:$newTemplate){ForEach(StudioTemplate.allCases){Label($0.rawValue,systemImage:$0.icon).tag($0)}}}Section{Button("Create Project"){store.newProject(template:newTemplate,name:newName.trimmingCharacters(in:.whitespacesAndNewlines).isEmpty ? nil:newName);showNewProject=false}.buttonStyle(.borderedProminent)}}.navigationTitle("New ReyForge App").toolbar{ToolbarItem(placement:.cancellationAction){Button("Cancel"){showNewProject=false}}}}}}
    private var desktop:some View{VStack(spacing:0){ReyForgeTopBar(showGitHub:$showGitHub,showNewProject:$showNewProject,bottomPanel:$bottomPanel);Divider();HStack(spacing:0){VStack(spacing:0){Picker("Tool",selection:$leftPanel){ForEach([StudioPanel.library,.templates,.vibe]){Image(systemName:$0.icon).tag($0)}}.pickerStyle(.segmented).padding(10);switch leftPanel{case .library:ComponentLibraryPanel();case .templates:TemplatePanel();case .vibe:VibeCodingPanel();default:EmptyView()}}.frame(width:265).background(.background);Divider();VStack(spacing:0){ReyForgeCanvas().frame(maxWidth:.infinity,maxHeight:.infinity);if let bottomPanel{Divider();StudioBottomPanel(panel:bottomPanel).frame(height:270)}};Divider();StudioInspector().frame(width:330).background(.background)}}}
    private var compact:some View{NavigationStack{VStack(spacing:0){HStack(spacing:10){Button{showLeftPanel=true}label:{Label("Add",systemImage:"plus.square.on.square")};Spacer();Menu{Button{bottomPanel=.vibe}label:{Label("Vibe AI",systemImage:"sparkles")};Button{bottomPanel=.code}label:{Label("Code",systemImage:"chevron.left.forwardslash.chevron.right")};Button{bottomPanel=.widget}label:{Label("Widget",systemImage:"square.grid.2x2")};Button{bottomPanel=.build}label:{Label("Build",systemImage:"hammer")}}label:{Label("Tools",systemImage:"wrench.and.screwdriver")};Button{showInspector=true}label:{Label("Edit",systemImage:"slider.horizontal.3")}}.font(.subheadline.weight(.medium)).padding(.horizontal,12).frame(height:48).background(.bar);ReyForgeCanvas()}.navigationTitle(store.selected?.name ?? "ReyForge").navigationBarTitleDisplayMode(.inline).toolbar{ToolbarItem(placement:.topBarLeading){Button{showNewProject=true}label:{Image(systemName:"plus")}};ToolbarItem(placement:.topBarTrailing){Button{showGitHub=true}label:{Image(systemName:github.hasCredential ? "icloud.and.arrow.up.fill":"icloud.and.arrow.up")}}}}.sheet(isPresented:$showLeftPanel){NavigationStack{TabView{ComponentLibraryPanel().tabItem{Label("Components",systemImage:"square.grid.2x2")};TemplatePanel().tabItem{Label("Templates",systemImage:"square.stack.3d.up")}}.navigationTitle("Insert").toolbar{ToolbarItem(placement:.topBarTrailing){Button("Done"){showLeftPanel=false}}}}.presentationDetents([.medium,.large])}.sheet(isPresented:$showInspector){NavigationStack{StudioInspector().navigationTitle("Inspector").toolbar{ToolbarItem(placement:.topBarTrailing){Button("Done"){showInspector=false}}}}.presentationDetents([.medium,.large])}.sheet(item:$bottomPanel){panel in NavigationStack{StudioBottomPanel(panel:panel).navigationTitle(panel.rawValue).toolbar{ToolbarItem(placement:.topBarTrailing){Button("Done"){bottomPanel=nil}}}}.presentationDetents(panel == .vibe ? [.large]:[.medium,.large])}}
}

private struct ReyForgeTopBar:View{@EnvironmentObject private var store:StudioStore;@EnvironmentObject private var github:GitHubBuildManager;@Binding var showGitHub:Bool;@Binding var showNewProject:Bool;@Binding var bottomPanel:StudioPanel?;var body:some View{HStack(spacing:12){ZStack{RoundedRectangle(cornerRadius:10).fill(.indigo.gradient);Image(systemName:"hammer.fill").foregroundStyle(.white)}.frame(width:34,height:34);VStack(alignment:.leading,spacing:0){Text("ReyForge").font(.headline.weight(.bold));Text("Native iOS Studio").font(.caption2).foregroundStyle(.secondary)};Divider().frame(height:26);Menu{ForEach(store.projects){p in Button{store.selectedID=p.id;store.selectedComponentID=p.components.first?.id}label:{if store.selectedID==p.id{Label(p.name,systemImage:"checkmark")}else{Text(p.name)}}};Divider();Button{showNewProject=true}label:{Label("New Project",systemImage:"plus")};Button{store.duplicateCurrent()}label:{Label("Duplicate",systemImage:"doc.on.doc")}}label:{HStack(spacing:5){Text(store.selected?.name ?? "Project").lineLimit(1);Image(systemName:"chevron.down").font(.caption2)}};Spacer();HStack(spacing:2){ForEach([StudioPanel.vibe,.code,.widget,.build]){p in Button{bottomPanel=bottomPanel==p ? nil:p}label:{Label(p.rawValue,systemImage:p.icon).labelStyle(.iconOnly).frame(width:34,height:30)}.background(bottomPanel==p ? Color.indigo.opacity(0.12):Color.clear,in:RoundedRectangle(cornerRadius:7))}};Button{showGitHub=true}label:{Label(github.isBuilding ? "Building":"GitHub",systemImage:github.hasCredential ? "icloud.and.arrow.up.fill":"icloud.and.arrow.up")}.buttonStyle(.bordered)}.padding(.horizontal,12).frame(height:56).background(.bar)}}

private struct ComponentLibraryPanel:View{@EnvironmentObject private var store:StudioStore;@State private var search="";private var groups:[(String,[StudioComponentKind])]{let f=StudioComponentKind.allCases.filter{search.isEmpty||$0.rawValue.localizedCaseInsensitiveContains(search)};return ["Display","Inputs","Actions","Layout","Advanced"].map{($0,f.filter{$0.category==$0})}.filter{!$0.1.isEmpty}};var body:some View{List{ForEach(["Display","Inputs","Actions","Layout","Advanced"],id:\.self){cat in let items=StudioComponentKind.allCases.filter{($0.category==cat)&&(search.isEmpty||$0.rawValue.localizedCaseInsensitiveContains(search))};if !items.isEmpty{Section(cat){ForEach(items){kind in Button{store.add(kind)}label:{HStack(spacing:10){Image(systemName:kind.icon).frame(width:28,height:28).background(.indigo.opacity(0.10),in:RoundedRectangle(cornerRadius:7));Text(kind.rawValue).foregroundStyle(.primary);Spacer();Image(systemName:"plus.circle").foregroundStyle(.secondary)}}.buttonStyle(.plain).onDrag{NSItemProvider(object:kind.rawValue as NSString)}}}}}.searchable(text:$search,prompt:"Find a native component").listStyle(.sidebar)}}

private struct TemplatePanel:View{@EnvironmentObject private var store:StudioStore;var body:some View{List{Section("Full-featured starters"){ForEach(StudioTemplate.allCases){t in Button{store.newProject(template:t)}label:{HStack(spacing:12){Image(systemName:t.icon).font(.title3).frame(width:36,height:36).background(.indigo.opacity(0.10),in:RoundedRectangle(cornerRadius:9));VStack(alignment:.leading,spacing:2){Text(t.rawValue).foregroundStyle(.primary).font(.subheadline.weight(.semibold));Text(desc(t)).font(.caption2).foregroundStyle(.secondary)}}}.buttonStyle(.plain)}}}.listStyle(.sidebar)};private func desc(_ t:StudioTemplate)->String{switch t{case .blank:return "Minimal editable canvas";case .login:return "Auth fields, action and link";case .dashboard:return "Gauge, progress, list and actions";case .settings:return "Toggles, picker, slider and navigation";case .profile:return "Image, profile fields and sharing";case .commerce:return "Product UI, quantity and cart action";case .componentGallery:return "Almost every ReyForge native control at once";case .widgetStarter:return "App + WidgetKit Home Screen target"}}}

private struct ReyForgeCanvas:View{@EnvironmentObject private var store:StudioStore;var body:some View{GeometryReader{geo in let scale=min(max(0.45,min((geo.size.width-34)/390,(geo.size.height-34)/844)),1.0);ZStack{Color(uiColor:.secondarySystemGroupedBackground).ignoresSafeArea();VStack(spacing:8){HStack{Label("iPhone 390 × 844",systemImage:"iphone").font(.caption.weight(.medium)).foregroundStyle(.secondary);Spacer();if let c=store.selectedComponent{Text("x \(Int(c.x)) y \(Int(c.y)) \(Int(c.width))×\(Int(c.height))").font(.caption2.monospacedDigit()).foregroundStyle(.secondary)}}.frame(width:390*scale);ZStack(alignment:.topLeading){RoundedRectangle(cornerRadius:46,style:.continuous).fill(Color(uiColor:.systemBackground)).frame(width:390,height:844);VStack{Capsule().fill(.primary.opacity(0.85)).frame(width:104,height:28);Spacer()}.frame(width:390,height:844).allowsHitTesting(false);if let p=store.selected{ForEach(p.components){c in MovableStudioComponent(component:c,isSelected:store.selectedComponentID==c.id,canvasScale:scale)}}}.frame(width:390,height:844).clipShape(RoundedRectangle(cornerRadius:46,style:.continuous)).overlay{RoundedRectangle(cornerRadius:46).stroke(.primary.opacity(0.16),lineWidth:2)}.shadow(radius:20,y:10).scaleEffect(scale,anchor:.topLeading).frame(width:390*scale,height:844*scale,alignment:.topLeading).onDrop(of:[.text],isTargeted:nil){providers,location in guard let provider=providers.first else{return false};provider.loadObject(ofClass:NSString.self){value,_ in guard let raw=value as? String,let kind=StudioComponentKind(rawValue:raw)else{return};Task{@MainActor in store.add(kind,at:CGPoint(x:location.x/scale,y:location.y/scale))}};return true}}.padding(12)}}}}}

private struct MovableStudioComponent:View{@EnvironmentObject private var store:StudioStore;let component:StudioComponent;let isSelected:Bool;let canvasScale:CGFloat;@State private var dragOrigin:CGPoint?;@State private var resizeOrigin:CGSize?;var body:some View{StudioComponentRenderer(component:component).frame(width:component.width,height:component.height).background(isSelected ? Color.indigo.opacity(0.06):Color.clear).overlay{if isSelected{RoundedRectangle(cornerRadius:max(4,component.cornerRadius)).stroke(.indigo,style:StrokeStyle(lineWidth:2,dash:[5,3]))}}.overlay(alignment:.bottomTrailing){if isSelected{Image(systemName:"arrow.up.left.and.arrow.down.right").font(.caption2.weight(.bold)).foregroundStyle(.white).frame(width:24,height:24).background(.indigo,in:Circle()).offset(x:10,y:10).gesture(DragGesture().onChanged{v in if resizeOrigin==nil{resizeOrigin=CGSize(width:component.width,height:component.height)};let o=resizeOrigin ?? .zero;store.selectedComponentID=component.id;store.resizeSelected(width:o.width+v.translation.width/canvasScale,height:o.height+v.translation.height/canvasScale)}.onEnded{_ in resizeOrigin=nil})}}.position(x:component.x,y:component.y).contentShape(Rectangle()).onTapGesture{store.selectedComponentID=component.id}.gesture(DragGesture(minimumDistance:3).onChanged{v in store.selectedComponentID=component.id;if dragOrigin==nil{dragOrigin=CGPoint(x:component.x,y:component.y)};let o=dragOrigin ?? CGPoint(x:component.x,y:component.y);store.moveSelected(to:CGPoint(x:o.x+v.translation.width/canvasScale,y:o.y+v.translation.height/canvasScale))}.onEnded{_ in dragOrigin=nil})}}

private struct StudioComponentRenderer:View{let component:StudioComponent;@State private var input="";@State private var toggle=true;@State private var value=0.5;@State private var count=1;@State private var choice="One";@State private var date=Date();@State private var tint=Color.indigo;var body:some View{Group{switch component.kind{case .text:Text(component.text).font(.system(size:component.fontSize,weight:.semibold)).frame(maxWidth:.infinity,alignment:.leading);case .button:Text(component.text).font(.headline).frame(maxWidth:.infinity,maxHeight:.infinity).background(.indigo.gradient,in:RoundedRectangle(cornerRadius:component.cornerRadius)).foregroundStyle(.white);case .textField:TextField(component.text,text:$input).textFieldStyle(.roundedBorder);case .secureField:SecureField(component.text,text:$input).textFieldStyle(.roundedBorder);case .textEditor:TextEditor(text:$input).overlay{RoundedRectangle(cornerRadius:8).stroke(.quaternary)}.overlay(alignment:.topLeading){if input.isEmpty{Text(component.text).foregroundStyle(.secondary).padding(8)}};case .image:Image(systemName:component.text.isEmpty ? "photo":component.text).resizable().scaledToFit().padding(8);case .symbol:Image(systemName:component.text.isEmpty ? "sparkles":component.text).font(.system(size:min(component.width,component.height)*0.48)).foregroundStyle(.indigo);case .label:Label(component.text,systemImage:component.detail.isEmpty ? "star.fill":component.detail);case .toggle:Toggle(component.text,isOn:$toggle);case .slider:VStack(alignment:.leading,spacing:2){Text(component.text).font(.caption);Slider(value:$value)};case .stepper:Stepper("\(component.text): \(count)",value:$count);case .picker:Picker(component.text,selection:$choice){ForEach(component.options,id:\.self){Text($0).tag($0)}};case .datePicker:DatePicker(component.text,selection:$date);case .colorPicker:ColorPicker(component.text,selection:$tint);case .progress:VStack(spacing:8){ProgressView(value:component.value);Text(component.text).font(.caption)};case .gauge:Gauge(value:component.value){Text(component.text)}.gaugeStyle(.accessoryCircular);case .divider:Divider();case .spacer:Label("Spacer",systemImage:"arrow.up.and.down").font(.caption).foregroundStyle(.secondary).frame(maxWidth:.infinity,maxHeight:.infinity).background(.quaternary,in:RoundedRectangle(cornerRadius:6));case .link:Label(component.text,systemImage:"link").foregroundStyle(.indigo);case .menu:Menu(component.text){Button("Option 1"){};Button("Option 2"){}};case .navigationLink:HStack{Text(component.text);Spacer();Image(systemName:"chevron.right")}.padding(.horizontal,10);case .list:VStack(alignment:.leading,spacing:0){ForEach(1...4,id:\.self){i in HStack{Image(systemName:"circle.fill").font(.caption2);Text("\(component.text) \(i)");Spacer()}.padding(8);Divider()}}.background(.quaternary.opacity(0.4),in:RoundedRectangle(cornerRadius:10));case .scrollView:ScrollView{VStack{ForEach(1...6,id:\.self){Text("Scrollable item \($0)").frame(maxWidth:.infinity).padding(6).background(.quaternary,in:RoundedRectangle(cornerRadius:6))}}};case .vStack:VStack(spacing:6){Text("VStack");RoundedRectangle(cornerRadius:4).fill(.quaternary);RoundedRectangle(cornerRadius:4).fill(.quaternary)}.padding(8).overlay{RoundedRectangle(cornerRadius:8).stroke(.quaternary)};case .hStack:HStack(spacing:6){Text("H");RoundedRectangle(cornerRadius:4).fill(.quaternary);RoundedRectangle(cornerRadius:4).fill(.quaternary)}.padding(8).overlay{RoundedRectangle(cornerRadius:8).stroke(.quaternary)};case .zStack:ZStack{RoundedRectangle(cornerRadius:10).fill(.indigo.opacity(0.12));Circle().fill(.indigo.opacity(0.25)).padding(20);Text("ZStack")};case .form:VStack(alignment:.leading){Text("Form").font(.headline);TextField("Field",text:$input).textFieldStyle(.roundedBorder);Toggle("Option",isOn:$toggle)}.padding(10).background(.quaternary.opacity(0.35),in:RoundedRectangle(cornerRadius:10));case .section:VStack(alignment:.leading){Text(component.text).font(.caption).foregroundStyle(.secondary);Divider();Text("Section content")}.padding(10).background(.quaternary.opacity(0.3),in:RoundedRectangle(cornerRadius:10));case .capsule:Capsule().fill(.indigo.opacity(0.18)).overlay{Text(component.text)};case .roundedRectangle:RoundedRectangle(cornerRadius:component.cornerRadius).fill(.indigo.opacity(0.16)).overlay{Text(component.text)};case .circle:Circle().fill(.indigo.opacity(0.18)).overlay{Text(component.text).font(.caption)};case .webView:VStack(spacing:5){Image(systemName:"safari").font(.largeTitle);Text(component.detail).font(.caption2).lineLimit(1)}.frame(maxWidth:.infinity,maxHeight:.infinity).background(.quaternary.opacity(0.35),in:RoundedRectangle(cornerRadius:12));case .map:VStack(spacing:5){Image(systemName:"map.fill").font(.largeTitle).foregroundStyle(.indigo);Text(component.detail.isEmpty ? "Map":component.detail).font(.caption)}.frame(maxWidth:.infinity,maxHeight:.infinity).background(.quaternary.opacity(0.35),in:RoundedRectangle(cornerRadius:12));case .shareLink:Label(component.text,systemImage:"square.and.arrow.up").padding(8).background(.quaternary,in:Capsule())}}.clipped()}}

private struct StudioInspector:View{@EnvironmentObject private var store:StudioStore;@State private var newActionKind:StudioActionKind=.showAlert;var body:some View{List{if let c=store.selectedComponent{Section("Component"){LabeledContent("Type",value:c.kind.rawValue);if ![StudioComponentKind.divider,.spacer].contains(c.kind){TextField("Text / label",text:stringBinding(\.text))};if [.image,.symbol,.label,.link,.navigationLink,.webView,.map,.shareLink].contains(c.kind){TextField("Detail / URL / symbol",text:stringBinding(\.detail))}};Section("Position & Size"){HStack{Text("X");Slider(value:doubleBinding(\.x),in:20...370);Text("\(Int(c.x))").monospacedDigit().frame(width:34)};HStack{Text("Y");Slider(value:doubleBinding(\.y),in:30...820);Text("\(Int(c.y))").monospacedDigit().frame(width:34)};HStack{Text("W");Slider(value:doubleBinding(\.width),in:44...370);Text("\(Int(c.width))").monospacedDigit().frame(width:34)};HStack{Text("H");Slider(value:doubleBinding(\.height),in:28...500);Text("\(Int(c.height))").monospacedDigit().frame(width:34)}};Section("Style"){HStack{Text("Corner");Slider(value:doubleBinding(\.cornerRadius),in:0...40);Text("\(Int(c.cornerRadius))")};HStack{Text("Font");Slider(value:doubleBinding(\.fontSize),in:10...44);Text("\(Int(c.fontSize))")};HStack{Text("Value");Slider(value:doubleBinding(\.value),in:0...1);Text("\(Int(c.value*100))%")}};Section("Logic"){ForEach(c.actions){ActionEditor(action:$0)};Picker("New action",selection:$newActionKind){ForEach(StudioActionKind.allCases){Label($0.rawValue,systemImage:$0.icon).tag($0)}};Button{store.addAction(newActionKind)}label:{Label("Add Logic Action",systemImage:"plus.circle")}};Section{Button(role:.destructive){store.deleteSelectedComponent()}label:{Label("Delete Component",systemImage:"trash")}}}else{ContentUnavailableView("Select a component",systemImage:"cursorarrow.click")}}.listStyle(.sidebar)};private func stringBinding(_ kp:WritableKeyPath<StudioComponent,String>)->Binding<String>{Binding(get:{store.selectedComponent?[keyPath:kp] ?? ""},set:{v in guard var c=store.selectedComponent else{return};c[keyPath:kp]=v;store.updateComponent(c)})};private func doubleBinding(_ kp:WritableKeyPath<StudioComponent,Double>)->Binding<Double>{Binding(get:{store.selectedComponent?[keyPath:kp] ?? 0},set:{v in guard var c=store.selectedComponent else{return};c[keyPath:kp]=v;store.updateComponent(c)})}}

private struct ActionEditor:View{@EnvironmentObject private var store:StudioStore;let action:StudioAction;var body:some View{VStack(alignment:.leading,spacing:6){HStack{Label(action.kind.rawValue,systemImage:action.kind.icon).font(.caption.weight(.semibold));Spacer();Button(role:.destructive){store.deleteAction(action.id)}label:{Image(systemName:"xmark.circle")}.buttonStyle(.plain)};TextField("Key / title",text:Binding(get:{current?.key ?? action.key},set:{v in update{$0.key=v}}));TextField("Value / destination / URL",text:Binding(get:{current?.value ?? action.value},set:{v in update{$0.value=v}}))}.padding(.vertical,4)};private var current:StudioAction?{store.selectedComponent?.actions.first{$0.id==action.id}};private func update(_ change:(inout StudioAction)->Void){guard var a=current else{return};change(&a);store.updateAction(a)}}

private struct StudioBottomPanel:View{let panel:StudioPanel;var body:some View{switch panel{case .vibe:VibeCodingPanel();case .code:StudioCodePanel();case .build:StudioBuildPanel();case .widget:WidgetExportPanel();case .library:ComponentLibraryPanel();case .templates:TemplatePanel()}}}

private struct VibeCodingPanel:View{@EnvironmentObject private var store:StudioStore;@State private var prompt="";@State private var rawOutput="";@State private var pendingPatch:VibePatch?;@State private var isGenerating=false;@State private var message="Describe a feature. SmolLM2 runs locally on the device.";var body:some View{VStack(alignment:.leading,spacing:10){HStack{ZStack{RoundedRectangle(cornerRadius:8).fill(.indigo.gradient);Image(systemName:"sparkles").foregroundStyle(.white)}.frame(width:32,height:32);VStack(alignment:.leading,spacing:0){Text("ReyForge Vibe").font(.headline);Text(LocalVibeModel.shared.isBundled ? "SmolLM2-360M • local • no API":"Local model resource missing").font(.caption2).foregroundStyle(.secondary)};Spacer();if isGenerating{ProgressView()}};TextEditor(text:$prompt).font(.body).frame(minHeight:68,maxHeight:100).overlay{RoundedRectangle(cornerRadius:10).stroke(.quaternary)}.overlay(alignment:.topLeading){if prompt.isEmpty{Text("e.g. Add a settings screen with notification and Face ID toggles, then save locally").foregroundStyle(.secondary).padding(8).allowsHitTesting(false)}};HStack{Text(message).font(.caption).foregroundStyle(.secondary).lineLimit(2);Spacer();if pendingPatch != nil{Button("Apply Changes"){applyPatch()}.buttonStyle(.borderedProminent)};Button{generate()}label:{Label(isGenerating ? "Thinking…":"Vibe Build",systemImage:"wand.and.stars")}.buttonStyle(.borderedProminent).disabled(isGenerating||prompt.trimmingCharacters(in:.whitespacesAndNewlines).isEmpty)};if !rawOutput.isEmpty{DisclosureGroup("Local model patch"){ScrollView{Text(rawOutput).font(.system(.caption2,design:.monospaced)).textSelection(.enabled).frame(maxWidth:.infinity,alignment:.leading)}}}}.padding(12).background(.background)};private func generate(){guard let project=store.selected else{return};let request=prompt;isGenerating=true;message="Running SmolLM2 locally…";pendingPatch=nil;rawOutput="";Task{let result:Result<String,Error>=await withCheckedContinuation{continuation in DispatchQueue.global(qos:.userInitiated).async{do{continuation.resume(returning:.success(try LocalVibeModel.shared.propose(prompt:request,project:project)))}catch{continuation.resume(returning:.failure(error))}}};switch result{case .success(let output):rawOutput=output;let patch=VibePatchParser.parse(output,fallbackPrompt:request,project:project);pendingPatch=patch;message=patch.summary;case .failure(let error):let patch=VibePatchParser.heuristic(prompt:request,project:project);rawOutput="Local model error: \(error.localizedDescription)\nApplied deterministic offline fallback.";pendingPatch=patch;message="SmolLM2 fallback is ready to apply."};isGenerating=false}};private func applyPatch(){guard let patch=pendingPatch else{return};store.updateProject{p in p.components.append(contentsOf:patch.components);for(k,v)in patch.variableUpdates{p.variables[k]=v};if let w=patch.widget{p.widget=w}};store.selectedComponentID=patch.components.last?.id ?? store.selectedComponentID;pendingPatch=nil;message="Applied. Everything remains draggable and editable."}}

private struct WidgetExportPanel:View{@EnvironmentObject private var store:StudioStore;var body:some View{Form{if let p=store.selected{Section("WidgetKit"){Toggle("Include Home Screen Widget",isOn:Binding(get:{store.selected?.widget.enabled ?? false},set:{v in store.updateProject{$0.widget.enabled=v}}));TextField("Display name",text:wb(\.displayName));TextField("Title",text:wb(\.title));TextField("Subtitle",text:wb(\.subtitle));TextField("SF Symbol",text:wb(\.symbol));Picker("Family",selection:wb(\.family)){Text("Small").tag("systemSmall");Text("Medium").tag("systemMedium");Text("Large").tag("systemLarge")};TextField("Deep link",text:wb(\.deepLink))};Section("Preview"){HStack(spacing:12){Image(systemName:p.widget.symbol).font(.title).foregroundStyle(.indigo);VStack(alignment:.leading){Text(p.widget.title).font(.headline);Text(p.widget.subtitle).font(.caption).foregroundStyle(.secondary)};Spacer()}.padding().background(.quaternary.opacity(0.4),in:RoundedRectangle(cornerRadius:18))};Text("When enabled, the GitHub macOS build creates a WidgetKit app-extension target embedded in the generated IPA. Launch the installed app once, then add its widget from the iOS Home Screen widget gallery.").font(.footnote).foregroundStyle(.secondary)}}};private func wb(_ kp:WritableKeyPath<StudioWidgetConfig,String>)->Binding<String>{Binding(get:{store.selected?.widget[keyPath:kp] ?? ""},set:{v in store.updateProject{$0.widget[keyPath:kp]=v}})}}

private struct StudioBuildPanel:View{@EnvironmentObject private var store:StudioStore;@EnvironmentObject private var github:GitHubBuildManager;var body:some View{VStack(alignment:.leading,spacing:10){HStack{VStack(alignment:.leading,spacing:1){Text("Native iOS Build").font(.headline);Text(github.status).font(.caption).foregroundStyle(.secondary)};Spacer();if github.isBuilding{ProgressView()};Button{guard let p=store.selected else{return};Task{await github.build(project:p)}}label:{Label("Build IPA",systemImage:"hammer.fill")}.buttonStyle(.borderedProminent).disabled(github.isBuilding||!github.hasCredential||store.selected==nil)};if !github.hasCredential{Label("Connect GitHub from the cloud button first.",systemImage:"key").font(.caption).foregroundStyle(.secondary)};if let e=github.lastError{Text(e).font(.caption).foregroundStyle(.red).textSelection(.enabled)};if let run=github.lastRunURL{Link("Open GitHub Actions Run",destination:run)};if let ipa=github.ipaURL{HStack{Label(ipa.lastPathComponent,systemImage:"shippingbox.fill");Spacer();ShareLink(item:ipa){Label("Share / Feather",systemImage:"square.and.arrow.up")}}};Spacer()}.padding(12).background(.background)}}

private struct StudioCodePanel:View{@EnvironmentObject private var store:StudioStore;var body:some View{ScrollView{Text(code).font(.system(.caption,design:.monospaced)).textSelection(.enabled).frame(maxWidth:.infinity,alignment:.leading).padding(12)}.background(.background)};private var code:String{guard let p=store.selected else{return "// No project selected"};var l=["import SwiftUI","","struct ContentView: View {","    var body: some View {","        ZStack {"];for c in p.components{let t=c.text.replacingOccurrences(of:"\"",with:"\\\"");switch c.kind{case .text:l.append("            Text(\"\(t)\")");case .button:l.append("            Button(\"\(t)\") { /* \(c.actions.count) action(s) */ }");case .textField:l.append("            TextField(\"\(t)\", text: .constant(\"\"))");case .secureField:l.append("            SecureField(\"\(t)\", text: .constant(\"\"))");case .toggle:l.append("            Toggle(\"\(t)\", isOn: .constant(true))");default:l.append("            // \(c.kind.rawValue): \(t)")};l.append("                .frame(width: \(Int(c.width)), height: \(Int(c.height)))");l.append("                .position(x: \(Int(c.x)), y: \(Int(c.y)))")};l += ["        }","        .frame(width: 390, height: 844)","    }","}"];if p.widget.enabled{l.append("\n// WidgetKit extension enabled: \(p.widget.displayName)")};return l.joined(separator:"\n")}}

private struct ReyForgeGitHubSettings:View{@Environment(\.dismiss) private var dismiss;@EnvironmentObject private var github:GitHubBuildManager;@State private var showToken=false;var body:some View{NavigationStack{Form{Section("Repository"){TextField("Owner",text:$github.owner).textInputAutocapitalization(.never).autocorrectionDisabled();TextField("Repository",text:$github.repo).textInputAutocapitalization(.never).autocorrectionDisabled()};Section("Fine-grained token"){if showToken{TextField("github_pat_…",text:$github.token).textInputAutocapitalization(.never).autocorrectionDisabled()}else{SecureField("github_pat_…",text:$github.token).textInputAutocapitalization(.never).autocorrectionDisabled()};Toggle("Show token",isOn:$showToken);Button("Save to iOS Keychain"){github.saveCredential()}};Section("Permissions"){Label("Contents: Read and write",systemImage:"doc.badge.gearshape");Label("Actions: Read",systemImage:"play.square.stack");Text("The token is kept in this device's Keychain. ReyForge uploads declarative project JSON; GitHub generates and returns the IPA.").font(.footnote).foregroundStyle(.secondary)};if github.hasCredential{Section{Button("Disconnect",role:.destructive){github.disconnect()}}}}.navigationTitle("ReyForge Cloud Build").toolbar{ToolbarItem(placement:.topBarTrailing){Button("Done"){dismiss()}}}}}}
